/**
 * 2D hand illustration (seen from the back of the hand, since the palm side
 * touches the face). Ported from the 안면마비 재활 prototype (hand2d.js) and
 * extended with thumb, hooked and intra-oral fingers.
 * All coordinates are SVG screen px; U = px per face unit.
 */
export type V = [number, number];

const SKIN = '#F1C09F';
const SKIN_DARK = '#D9A07E';
const NAIL = '#FBE9DF';

const add = (a: V, b: V): V => [a[0] + b[0], a[1] + b[1]];
const sub = (a: V, b: V): V => [a[0] - b[0], a[1] - b[1]];
const mul = (a: V, k: number): V => [a[0] * k, a[1] * k];
const len = (a: V) => Math.hypot(a[0], a[1]);
const norm = (a: V): V => {
  const l = len(a) || 1;
  return [a[0] / l, a[1] / l];
};
const perp = (a: V): V => [-a[1], a[0]];
const dot = (a: V, b: V) => a[0] * b[0] + a[1] * b[1];
const P = (p: V) => `${p[0].toFixed(1)},${p[1].toFixed(1)}`;
const ang = (d: V) => (Math.atan2(d[1], d[0]) * 180) / Math.PI;

type Item = { t: 'seg'; a: V; b: V; w: number } | { t: 'poly'; d: string };

/** Parts are drawn twice (outline colour, then skin) so the hand reads as one silhouette. */
class Shape {
  items: Item[] = [];
  dashed: Item[] = [];
  details: string[] = [];
  seg(a: V, b: V, w: number, dashed = false) {
    (dashed ? this.dashed : this.items).push({ t: 'seg', a, b, w });
  }
  poly(d: string) {
    this.items.push({ t: 'poly', d });
  }
  render(color: string): string {
    const draw = (list: Item[], extra: number, attr = '') =>
      list
        .map((i) =>
          i.t === 'seg'
            ? `<line x1="${i.a[0].toFixed(1)}" y1="${i.a[1].toFixed(1)}" x2="${i.b[0].toFixed(1)}" y2="${i.b[1].toFixed(1)}" stroke-width="${(i.w + extra).toFixed(1)}"${attr}/>`
            : `<path d="${i.d}" stroke-width="${extra}"/>`,
        )
        .join('');
    return `<g stroke="${color}" fill="${color}" stroke-linecap="round" stroke-linejoin="round">${draw(this.items, 5)}</g>
      <g stroke="${SKIN}" fill="${SKIN}" stroke-linecap="round" stroke-linejoin="round">${draw(this.items, 0)}</g>
      ${
        this.dashed.length
          ? `<g stroke="${color}" fill="none" stroke-linecap="round">${this.dashed.map((i) => (i.t === 'seg' ? `<line x1="${i.a[0]}" y1="${i.a[1]}" x2="${i.b[0]}" y2="${i.b[1]}" stroke-width="${i.w + 4}" stroke-dasharray="6 5" opacity="0.9"/>` : '')).join('')}</g>
      <g stroke="${SKIN}" stroke-linecap="round" opacity="0.55">${draw(this.dashed, -2)}</g>`
          : ''
      }
      <g>${this.details.join('')}</g>`;
  }
}

/** One finger from tip to base (knuckle): distal, middle and proximal phalanges. */
function finger(
  sh: Shape,
  tip: V,
  base: V,
  w: number,
  o: { nail?: boolean; label?: string | null; labelColor?: string; dashed?: boolean } = {},
) {
  const d = sub(base, tip);
  const L = len(d);
  const F = norm(d);
  const dip = add(tip, mul(F, L * 0.27));
  const pip = add(tip, mul(F, L * 0.56));
  sh.seg(pip, base, w, o.dashed);
  sh.seg(dip, pip, w * 0.95, o.dashed);
  sh.seg(tip, dip, w * 0.9, o.dashed);
  if (o.dashed) {
    const lp = add(tip, mul(F, L * 0.35));
    sh.details.push(`<text x="${lp[0]}" y="${lp[1] + 4}" text-anchor="middle" class="finger-label" fill="${o.labelColor}">입안</text>`);
    return;
  }
  const N = perp(F);
  for (const [j, k] of [
    [dip, 0.34],
    [pip, 0.4],
  ] as const) {
    const a = add(j, mul(N, w * k));
    const b = sub(j, mul(N, w * k));
    const c = add(j, mul(F, 2.5));
    sh.details.push(`<path d="M${P(a)} Q${P(c)} ${P(b)}" fill="none" stroke="${SKIN_DARK}" stroke-width="1.3" stroke-linecap="round"/>`);
  }
  if (o.nail !== false) {
    const nc = add(tip, mul(F, L * 0.1));
    const nl = L * 0.17;
    const nw = w * 0.62;
    sh.details.push(
      `<rect x="${-nl / 2}" y="${-nw / 2}" width="${nl}" height="${nw}" rx="${nw * 0.45}" transform="translate(${P(nc)}) rotate(${ang(F)})" fill="${NAIL}" stroke="${SKIN_DARK}" stroke-width="0.9"/>`,
    );
  }
  if (o.label) {
    const lp = add(tip, mul(F, L * 0.72));
    sh.details.push(
      `<text x="${lp[0]}" y="${lp[1] + 4}" text-anchor="middle" class="finger-label" fill="${o.labelColor}">${o.label}</text>`,
    );
  }
}

function palmPath(topIdx: V, topPinky: V, wristPinky: V, wristIdx: V, D: V, K: V) {
  const thenar = add(add(wristIdx, mul(sub(topIdx, wristIdx), 0.45)), mul(K, -9));
  const hypo = add(add(wristPinky, mul(sub(topPinky, wristPinky), 0.5)), mul(K, 5));
  const knuckleMid = add(mul(add(topIdx, topPinky), 0.5), mul(D, -5));
  return `M${P(topIdx)} Q${P(knuckleMid)} ${P(topPinky)} Q${P(hypo)} ${P(wristPinky)} L${P(wristIdx)} Q${P(thenar)} ${P(topIdx)} Z`;
}

function forearm(sh: Shape, wristIdx: V, wristPinky: V, D: V) {
  const far = 380;
  const a = add(wristIdx, mul(D, far));
  const b = add(wristPinky, mul(D, far));
  const wa = add(a, mul(norm(sub(wristIdx, wristPinky)), 6));
  const wb = add(b, mul(norm(sub(wristPinky, wristIdx)), 6));
  sh.poly(`M${P(wristIdx)} L${P(wa)} L${P(wb)} L${P(wristPinky)} Z`);
}

export interface Pad {
  pos: V;
  /** Unit vector from the fingertip towards the wrist (screen). */
  F: V;
  label: string;
  intraoral?: boolean;
  hook?: boolean;
}

/** Hand pressing with one or two fingertips (index/middle/ring) or the thumb. */
export function fingerHand({ pads, U, color }: { pads: Pad[]; U: number; color: string }): string {
  const sh = new Shape();
  const D = norm(pads.reduce<V>((a, p) => add(a, p.F), [0, 0]));
  const center = mul(
    pads.reduce<V>((a, p) => add(a, p.pos), [0, 0]),
    1 / pads.length,
  );
  let K = perp(D);
  const fingers = pads.filter((p) => p.label !== '엄지');
  const thumb = pads.find((p) => p.label === '엄지');
  if (fingers.length >= 2 && dot(K, sub(fingers[1]!.pos, fingers[0]!.pos)) < 0) K = mul(K, -1);
  const w = 0.52 * U;
  const sp = w * 1.1;
  const reach = fingers.some((p) => p.hook) ? 2.2 : 3.3;
  const anchor = fingers.length
    ? mul(
        fingers.reduce<V>((a, p) => add(a, p.pos), [0, 0]),
        1 / fingers.length,
      )
    : center;
  const B = add(anchor, mul(D, reach * U));
  const Mi = add(B, mul(K, -sp * 0.5));
  const Mm = add(B, mul(K, sp * 0.5));
  const Mr = add(add(B, mul(K, sp * 1.5)), mul(D, 3));
  const Mp = add(add(B, mul(K, sp * 2.4)), mul(D, 9));
  const W = add(B, mul(D, 2.9 * U));
  const pw = sp * 3.4;
  const topIdx = add(Mi, mul(K, -w * 0.55));
  const topPinky = add(Mp, mul(K, w * 0.5));
  const wristIdx = add(W, mul(K, -pw * 0.28 + sp * 0.4));
  const wristPinky = add(W, mul(K, pw * 0.28 + sp * 0.9));
  forearm(sh, wristIdx, wristPinky, D);
  sh.poly(palmPath(topIdx, topPinky, wristPinky, wristIdx, D, K));
  // Folded fingers: only the first phalanx and knuckle show from the back.
  const used = new Set(fingers.map((p) => p.label));
  if (!used.has('약지')) finger(sh, add(Mr, mul(D, -0.85 * U)), Mr, w * 0.95, { nail: false });
  finger(sh, add(Mp, mul(D, -0.7 * U)), Mp, w * 0.85, { nail: false });
  if (!fingers.some((p) => p.label === '검지') && fingers.length) finger(sh, add(Mi, mul(D, -0.9 * U)), Mi, w, { nail: false });

  // Thumb: pressing thumb reaches its pad, otherwise tucked along the side.
  const tb = add(add(Mi, mul(K, -w * 0.7)), mul(D, 1.45 * U));
  if (thumb) {
    finger(sh, sub(thumb.pos, mul(norm(sub(tb, thumb.pos)), 0.28 * U)), tb, w * 1.1, {
      label: '엄지',
      labelColor: color,
      dashed: thumb.intraoral,
    });
  } else {
    const tDir = norm(add(mul(K, -0.75), mul(D, -0.65)));
    finger(sh, add(tb, mul(tDir, 1.9 * U)), tb, w * 1.05);
  }
  const together = fingers.length === 2 && len(sub(fingers[0]!.pos, fingers[1]!.pos)) < 1.3 * U;
  fingers.forEach((p, i) => {
    const base = p.label === '중지' || p.label === '약지' || i === 1 ? Mm : Mi;
    const tip = sub(p.pos, mul(norm(sub(base, p.pos)), 0.28 * U));
    finger(sh, tip, base, w, { label: together ? null : p.label, labelColor: color, dashed: p.intraoral });
  });
  if (together) {
    const c = add(mul(add(fingers[0]!.pos, fingers[1]!.pos), 0.5), mul(D, 2.3 * U));
    sh.details.push(
      `<text x="${c[0]}" y="${c[1] + 4}" text-anchor="middle" class="finger-label" fill="${color}">${fingers[0]!.label}·${fingers[1]!.label}</text>`,
    );
  }
  return sh.render(color);
}

/** Hand pressing with the palm (heel of the hand at `heel`). */
export function palmHand({
  heel,
  F,
  U,
  color,
  thumbSide,
  thumbTo,
  label = '손바닥',
}: {
  heel: V;
  F: V;
  U: number;
  color: string;
  thumbSide: V;
  /** A thumb pressing on its own (llsan 5:17): it reaches from the palm to this point. */
  thumbTo?: V;
  label?: string;
}): string {
  const sh = new Shape();
  const D = norm(F);
  let K = perp(D);
  if (dot(K, thumbSide) > 0) K = mul(K, -1);
  const w = 0.55 * U;
  const sp = w * 1.08;
  const pw = sp * 4.2;
  // The contact is the middle of the palm; fingers extend past it.
  const knuck = add(heel, mul(D, -1.3 * U));
  const base = add(heel, mul(D, 1.6 * U));
  const wristIdx = add(base, mul(K, -pw * 0.4));
  const wristPinky = add(base, mul(K, pw * 0.38));
  const topIdx = add(knuck, mul(K, -sp * 2.0));
  const topPinky = add(knuck, mul(K, sp * 2.0));
  const a1 = add(wristIdx, mul(D, 0.3 * U));
  const a2 = add(wristPinky, mul(D, 0.3 * U));
  sh.poly(`M${P(a1)} L${P(add(a1, mul(D, 380)))} L${P(add(a2, mul(D, 380)))} L${P(a2)} Z`);
  sh.poly(palmPath(topIdx, topPinky, wristPinky, wristIdx, mul(D, -1), K));
  (
    [
      [-1.5, 2.55],
      [-0.5, 2.85],
      [0.5, 2.7],
      [1.5, 2.15],
    ] as const
  ).forEach(([k, l], i) => {
    const b = add(add(knuck, mul(K, sp * k)), mul(D, Math.abs(k) * 3));
    const splay = norm(add(mul(D, -1), mul(K, k * 0.06)));
    finger(sh, add(b, mul(splay, l * U)), b, w * (i === 3 ? 0.85 : 1));
  });
  const tb = add(wristIdx, mul(D, -0.3 * U));
  const tDir = norm(add(mul(K, -0.8), mul(D, -0.6)));
  finger(sh, thumbTo ?? add(tb, mul(tDir, 2.0 * U)), tb, w * 1.08);
  if (label) sh.details.push(`<text x="${heel[0]}" y="${heel[1] + 5}" text-anchor="middle" class="finger-label" fill="${color}">${label}</text>`);
  return sh.render(color);
}

/** Soft shadow under a pressing fingertip. */
export function pressShadow(pos: V, F: V, r: number): string {
  const c = add(pos, mul(F, r * 0.25));
  return `<ellipse cx="${c[0]}" cy="${c[1]}" rx="${r}" ry="${r * 0.75}" transform="rotate(${ang(F)} ${c[0]} ${c[1]})" fill="rgba(120,60,35,0.38)" filter="url(#fsrSoft)"/>`;
}

/** Skin grain lines stretching behind a pulling finger. */
export function stretchLines(pos: V, m: V, amount: number, r: number): string {
  if (amount <= 0.02) return '';
  const back = mul(m, -1);
  const N = perp(m);
  let out = '';
  for (const k of [-1, 0, 1]) {
    const s = add(add(pos, mul(back, r + 4)), mul(N, k * 6));
    const e = add(s, mul(back, 10 + 12 * amount));
    out += `<line x1="${s[0]}" y1="${s[1]}" x2="${e[0]}" y2="${e[1]}" stroke="#B9785A" stroke-width="1.6" stroke-linecap="round" opacity="${0.75 * amount}"/>`;
  }
  return out;
}

export function lockBadge(x: number, y: number, color: string): string {
  return `<g transform="translate(${x},${y})">
    <circle r="11" fill="${color}" stroke="#fff" stroke-width="2"/>
    <rect x="-4.5" y="-1" width="9" height="7" rx="1.5" fill="#fff"/>
    <path d="M-2.8,-1 V-3.5 a2.8,2.8 0 0,1 5.6,0 V-1" fill="none" stroke="#fff" stroke-width="1.8"/>
  </g>`;
}
